1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.Locale;
5	import java.util.Map;
6	
7	/**
8	 * Derives an owner's {@code memberId} — the owner's single unified identity, formatted
9	 * {@code <REGION><FY><HASH8><CHK>} (e.g. {@code NSW261A2B3C4D7}):
10	 *
11	 * <ul>
12	 * <li>{@code REGION} is the region code derived from the postcode: look the postcode up
13	 * against the inclusive region ranges (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and,
14	 * only when the postcode is absent or in no known range, fall back to the fixed
15	 * city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), else
16	 * {@code UNKNOWN}.</li>
17	 * <li>{@code FY} is the last two digits of the fiscal year of the {@code registrationDate}
18	 * (fiscal years starting 1 July, identified by the calendar year in which they end).</li>
19	 * <li>{@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
20	 * {@code normalizedTelephone + lastName}, where the telephone is normalized to E.164 form
21	 * (an absent or unparseable telephone contributes an empty string).</li>
22	 * <li>{@code CHK} is a single Luhn check digit computed over the decimal digits of
23	 * {@code <REGION><FY><HASH8>}.</li>
24	 * </ul>
25	 *
26	 * <p>The whole owner identity — the {@code memberId} itself, the create audit record and the
27	 * derived locality — flows from this single value. There is no sequence number;
28	 * de-duplication of a collided {@code memberId} is handled in {@link AssignMemberId}.
29	 *
30	 * <p>Composition and decomposition of the id format live together here: {@link #of} builds an
31	 * id, {@link #regionOf} reads the region back out of one, and {@link #luhn} is the check over
32	 * its digits. The owner mapper's {@code locality} delegates to {@link #regionOf} rather than
33	 * re-deriving the format; its {@code fiscalYear} is a projection of the registration date
34	 * (see {@link FiscalYear#label}), not read back out of the id.
35	 *
36	 * <p>A plain utility (not an OfficeFloor function), so it may expose helpers without
37	 * tripping the one-public-method-per-function rule.
38	 */
39	public final class OwnerMemberId {
40	
41	    /** City -> canonical region, matching the fixed table used to validate postcodes. */
42	    private static final Map<String, String> CITY_REGION = Map.of(
43	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
44	
45	    /** Region -> inclusive 4-digit postcode range {low, high}. */
46	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
47	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
48	
49	    private OwnerMemberId() {
50	    }
51	
52	    /** The full {@code <REGION><FY><HASH8><CHK>} member id for the given owner fields. */
53	    public static String of(String postcode, String city, String telephone, String lastName,
54	            LocalDate registrationDate) {
55	        String body = region(postcode, city) + fiscalYear(registrationDate) + hash8(telephone, lastName);
56	        return body + luhn(body);
57	    }
58	
59	    /** The two-digit fiscal-year segment (e.g. {@code 26}) for a registration date. */
60	    private static String fiscalYear(LocalDate registrationDate) {
61	        return String.format("%02d", FiscalYear.of(registrationDate) % 100);
62	    }
63	
64	    /**
65	     * The REGION segment encoded in an existing member id, i.e. the leading run of letters that
66	     * precedes the {@code <FY>} digits (see {@link #of}). Returns {@code null} when {@code id} is
67	     * absent or carries no region segment. The inverse of {@link #of}: callers read the region
68	     * back out of the id here instead of re-parsing the format themselves.
69	     */
70	    public static String regionOf(String id) {
71	        if (id == null) {
72	            return null;
73	        }
74	        int i = 0;
75	        while (i < id.length() && Character.isLetter(id.charAt(i))) {
76	            i++;
77	        }
78	        return i > 0 ? id.substring(0, i) : null;
79	    }
80	
81	    /**
82	     * The Luhn check digit (0-9) computed over the decimal digits contained in {@code s}
83	     * (non-digit characters are ignored). Kept beside the id it checks so the id format and
84	     * the values derived from it share one home.
85	     */
86	    public static int luhn(String s) {
87	        int sum = 0;
88	        boolean dbl = true;
89	        for (int i = s.length() - 1; i >= 0; i--) {
90	            char c = s.charAt(i);
91	            if (c < '0' || c > '9') {
92	                continue;
93	            }
94	            int d = c - '0';
95	            if (dbl) {
96	                d *= 2;
97	                if (d > 9) {
98	                    d -= 9;
99	                }
100	            }
101	            sum += d;
102	            dbl = !dbl;
103	        }
104	        return (10 - (sum % 10)) % 10;
105	    }
106	
107	    /**
108	     * The region code derived from the postcode (range lookup), falling back to the fixed
109	     * city-to-region table when the postcode is absent or in no known range, else
110	     * {@code UNKNOWN}.
111	     */
112	    public static String region(String postcode, String city) {
113	        if (postcode != null) {
114	            try {
115	                int value = Integer.parseInt(postcode.trim());
116	                for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
117	                    int[] range = entry.getValue();
118	                    if (value >= range[0] && value <= range[1]) {
119	                        return entry.getKey();
120	                    }
121	                }
122	            }
123	            catch (NumberFormatException ex) {
124	                // not a numeric postcode; fall back to the city table
125	            }
126	        }
127	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
128	    }
129	
130	    /**
131	     * The region for a city by the fixed city-to-region table
132	     * ({@code Sydney->NSW, Melbourne->VIC, Brisbane->QLD}), or {@code null} when the city has
133	     * no known region. Unlike {@link #region}, this does not fall back to {@code UNKNOWN}; it
134	     * exposes the raw city table so callers such as {@code ValidatePostcode} share this one
135	     * source of the region reference data.
136	     */
137	    public static String regionForCity(String city) {
138	        return CITY_REGION.get(city);
139	    }
140	
141	    /**
142	     * The inclusive 4-digit postcode range {@code {low, high}} pinned for a region (NSW
143	     * 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code null} when the region has no pinned
144	     * range. The returned array is a copy, so callers cannot mutate the shared table.
145	     */
146	    public static int[] postcodeRange(String region) {
147	        int[] range = REGION_POSTCODES.get(region);
148	        return range == null ? null : range.clone();
149	    }
150	
151	    /**
152	     * The first 8 upper-case hex characters of SHA-256 over {@code normalizedTelephone +
153	     * lastName}, where the telephone is normalized to E.164 (an absent or unparseable
154	     * telephone, or an absent last name, contributes an empty string).
155	     */
156	    public static String hash8(String telephone, String lastName) {
157	        String tel = E164Telephone.normalizeOrNull(telephone);
158	        String normalizedTelephone = tel == null ? "" : tel;
159	        String last = lastName == null ? "" : lastName;
160	        return Sha256.hex(normalizedTelephone + last).substring(0, 8).toUpperCase(Locale.ROOT);
161	    }
162	}
163

